int process_unique_identifier(char *line, void *data) {
    struct context {
        struct {
            int refnum;
            int index;
        } header;
        int header_count;
        struct {
            int index;
            int refnum;
        } *headers;
        int clear_cache;
    } *ctx = (struct context *)data;
    int idx;

    if (line == NULL || data == NULL) {
        return -1;
    }

    // Trim whitespace from the line
    char *trimmed_line = line;
    while (*trimmed_line && isspace(*trimmed_line)) {
        trimmed_line++;
    }

    // Convert the line to an integer index
    if (sscanf(trimmed_line, "%d", &idx) != 1) {
        return -1;
    }

    // Check if the identifier exists in the headers
    int i;
    for (i = 0; i < ctx->header_count; i++) {
        if (ctx->headers[i].refnum == idx) {
            if (ctx->headers[i].index != ctx->header.index) {
                ctx->clear_cache = 1;
            }
            ctx->headers[i].index = ctx->header.index;
            return 0;
        }
    }

    // If not found, add a new header
    ctx->headers = realloc(ctx->headers, (ctx->header_count + 1) * sizeof(*ctx->headers));
    if (!ctx->headers) {
        return -1;
    }

    ctx->headers[ctx->header_count].refnum = idx;
    ctx->headers[ctx->header_count].index = ctx->header.index;
    ctx->header_count++;

    return 0;
}

int process_unique_identifier(char *line, void *data) {
    Context *context = (Context *)data;
    int index = atoi(line);
    char *identifier = line;

    // Trim whitespace
    while (isspace((unsigned char)*identifier)) {
        identifier++;
    }

    if (*identifier == '\0') {
        return -1; // Invalid identifier
    }

    Header *header = find_header(context, identifier);
    if (header == NULL) {
        header = add_header(context, identifier);
        if (header == NULL) {
            return -1; // Failed to add header
        }
    } else if (header->index != index) {
        context->clear_cache = 1; // Mark cache for clearing
    }

    header->reference_number = context->reference_number;
    header->index = index;
    return 0;
}

int process_unique_identifier(char *line, void *data) {
    Context *ctx = (Context *)data;
    int index = 0;
    char *endptr = NULL;

    if (!line || !ctx || !ctx->headers) {
        return -1;
    }

    line = trim_whitespace(line);
    index = strtol(line, &endptr, 10);
    if (*endptr != '\0') {
        return -1;
    }

    Header *header;
    int found = 0;

    for (int i = 0; i < ctx->header_count; ++i) {
        header = &ctx->headers[i];
        if (header->index == index) {
            found = 1;
            break;
        }
    }

    if (!found) {
        if (ctx->header_count >= ctx->header_capacity) {
            Header *new_headers = realloc(ctx->headers, (ctx->header_capacity + 1) * sizeof(Header));
            if (!new_headers) {
                return -1;
            }
            ctx->headers = new_headers;
            ++ctx->header_capacity;
        }
        header = &ctx->headers[ctx->header_count];
        header->index = index;
        ++ctx->header_count;
        ctx->needs_cache_clear = 1;
    }

    ctx->current_ref = index;
    return 0;
}

