    Context *ctx = (Context *)data;
    int index = 0;
    char *endptr;

    if (!line || !ctx) {
        return -1;
    }

    index = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != '\0') {
        return -1;
    }

    for (int i = 0; i < ctx->header_count; ++i) {
        if (ctx->headers[i].index == index) {
            if (ctx->headers[i].id != index) {
                ctx->clear_cache = 1;
            }
            ctx->headers[i].ref_num = ctx->message.ref_num;
            ctx->headers[i].index = index;
            return 0;
        }
    }

    if (ctx->header_count < MAX_HEADERS) {
        Header *hdr = &ctx->headers[ctx->header_count++];
        hdr->id = index;
        hdr->ref_num = ctx->message.ref_num;
        hdr->index = index;
        return 0;
