int process_unique_identifier(char *line, void *data) {
    Context *ctx = (Context *)data;
    int index = atoi(line);
    char *trimmed_line = strtok(line, " \t\n");

    if (!trimmed_line) {
        return -1;
    }

    // Find the header in context
    int i;
    int found = 0;
    for (i = 0; i < ctx->header_count; i++) {
        if (strcmp(ctx->headers[i].identifier, trimmed_line) == 0) {
            found = 1;
            if (ctx->headers[i].index != index) {
                ctx->clear_cache = 1;
            }
            ctx->headers[i].reference_number++;
            ctx->headers[i].index = index;
            break;
        }
    }

    if (!found) {
        // Add new header if not found
        if (ctx->header_count >= MAX_HEADERS) {
            return -1;
        }
        Header *header = &ctx->headers[ctx->header_count];
        strcpy(header->identifier, trimmed_line);
        header->index = index;
        header->reference_number = 1;
        ctx->header_count++;
    }

    return 0;
}
